CREATE TABLE IF NOT EXISTS inventory_revisions (
  rev_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  ingested_at DATETIME NOT NULL COMMENT 'when the system learned this version (occurred time is recorded_date)',
  recorded_date DATE NOT NULL,
  internal_sku VARCHAR(50) NOT NULL,
  channel_name VARCHAR(50) NOT NULL,
  std_item_id INT NOT NULL,
  purchase_cost DECIMAL(10,2) NOT NULL,
  fixed_cost DECIMAL(10,2) NOT NULL,
  logistics_cost DECIMAL(10,2) NOT NULL,
  channel_fee_rate DECIMAL(5,2) NOT NULL,
  promo_cost DECIMAL(10,2) NOT NULL DEFAULT 0,
  disposal_cost DECIMAL(10,2) NULL,
  vat_inclusive TINYINT(1) NOT NULL DEFAULT 1,
  pack_std_units DECIMAL(10,4) NOT NULL DEFAULT 1,
  current_selling_price INT NOT NULL,
  stock_qty INT NOT NULL,
  daily_sales_qty INT NOT NULL,
  min_price_floor INT NOT NULL,
  lifecycle_metric JSON NOT NULL,
  KEY idx_rev (recorded_date, internal_sku, channel_name, ingested_at)
);

CREATE TABLE IF NOT EXISTS promotions (
  promo_id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  category_l VARCHAR(50) NOT NULL DEFAULT '' COMMENT 'empty = every category',
  channel_name VARCHAR(50) NOT NULL DEFAULT '' COMMENT 'empty = every channel',
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  discount_pct DECIMAL(5,2) NULL,
  note VARCHAR(255) NULL,
  created_by VARCHAR(100) NOT NULL,
  KEY idx_promo_dates (start_date, end_date)
);

CREATE TABLE IF NOT EXISTS flyers (
  flyer_id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  source_name VARCHAR(120) NOT NULL,
  image_path VARCHAR(255) NOT NULL COMMENT 'relative to the inbox root',
  week_start DATE NOT NULL,
  status VARCHAR(10) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING until every item is decided, then REVIEWED',
  created_at DATETIME NOT NULL,
  reviewed_by VARCHAR(100) NULL,
  reviewed_at DATETIME NULL,
  KEY idx_flyer_status (status)
);

CREATE TABLE IF NOT EXISTS flyer_items (
  item_id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  flyer_id INT NOT NULL,
  name VARCHAR(80) NOT NULL,
  price INT NULL,
  confidence DECIMAL(4,3) NULL COMMENT 'the reader''s own estimate, 0 to 1; NULL = not given',
  category_l VARCHAR(50) NOT NULL DEFAULT '',
  status VARCHAR(10) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING, APPROVED or REJECTED; only APPROVED reaches analysis',
  KEY idx_item_flyer (flyer_id)
);

CREATE TABLE IF NOT EXISTS product_channel_map (
  platform VARCHAR(30) NOT NULL,
  channel_item_code VARCHAR(100) NOT NULL,
  std_item_id INT NOT NULL,
  pack_size_factor DECIMAL(10,4) NOT NULL DEFAULT 1,
  match_method VARCHAR(10) NOT NULL,
  match_confidence DECIMAL(4,3) NOT NULL,
  match_grade VARCHAR(10) NOT NULL DEFAULT 'SAME' COMMENT 'SAME | SIMILAR | SUBSTITUTE',
  reviewed_by VARCHAR(100) NULL,
  reviewed_at DATETIME NULL,
  PRIMARY KEY (platform, channel_item_code),
  FOREIGN KEY (std_item_id) REFERENCES master_products (std_item_id)
);

CREATE TABLE IF NOT EXISTS users (
  user_id INT AUTO_INCREMENT PRIMARY KEY,
  email VARCHAR(255) NOT NULL UNIQUE,
  name VARCHAR(100) NOT NULL,
  role ENUM('ADMIN','MD','BUYER') NOT NULL,
  password_hash VARCHAR(255) NOT NULL DEFAULT '',
  active TINYINT(1) NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS user_category_assignments (
  user_id INT NOT NULL,
  category_l VARCHAR(50) NOT NULL,
  category_m VARCHAR(50) NOT NULL DEFAULT '',
  PRIMARY KEY (user_id, category_l, category_m),
  FOREIGN KEY (user_id) REFERENCES users (user_id)
);

CREATE TABLE IF NOT EXISTS user_watchlists (
  watch_id INT AUTO_INCREMENT PRIMARY KEY,
  user_id INT NOT NULL,
  std_item_id INT NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  UNIQUE KEY uq_watch (user_id, std_item_id),
  FOREIGN KEY (user_id) REFERENCES users (user_id),
  FOREIGN KEY (std_item_id) REFERENCES master_products (std_item_id)
);

CREATE TABLE IF NOT EXISTS user_preferences (
  pref_id INT AUTO_INCREMENT PRIMARY KEY,
  user_id INT NOT NULL UNIQUE,
  alert_margin_bep DECIMAL(5,2) NOT NULL DEFAULT 10.00,
  ui_layout JSON NULL,
  FOREIGN KEY (user_id) REFERENCES users (user_id)
);

CREATE TABLE IF NOT EXISTS price_recommendations (
  rec_id BIGINT AUTO_INCREMENT PRIMARY KEY,
  created_at DATETIME NOT NULL,
  std_item_id INT NOT NULL,
  channel_name VARCHAR(50) NOT NULL,
  current_price INT NOT NULL,
  suggested_price INT NOT NULL,
  reason_code VARCHAR(40) NOT NULL,
  flags JSON NULL,
  status ENUM('PENDING','APPROVED','REJECTED','APPLIED','SUPPRESSED','REVERTED') NOT NULL DEFAULT 'PENDING',
  decided_by VARCHAR(100) NULL,
  decided_at DATETIME NULL,
  KEY idx_status (status, created_at),
  FOREIGN KEY (std_item_id) REFERENCES master_products (std_item_id)
);

CREATE TABLE IF NOT EXISTS review_queue (
  review_id BIGINT AUTO_INCREMENT PRIMARY KEY,
  created_at DATETIME NOT NULL,
  kind VARCHAR(30) NOT NULL,
  source VARCHAR(30) NOT NULL,
  item_key VARCHAR(255) NOT NULL,
  reason VARCHAR(255) NOT NULL,
  payload JSON NULL,
  status ENUM('OPEN','RESOLVED') NOT NULL DEFAULT 'OPEN',
  resolved_by VARCHAR(100) NULL,
  resolved_at DATETIME NULL,
  KEY idx_review (status, kind, source, item_key(100))
);

CREATE TABLE IF NOT EXISTS alert_log (
  alert_id BIGINT AUTO_INCREMENT PRIMARY KEY,
  created_at DATETIME NOT NULL,
  alert_key VARCHAR(255) NOT NULL,
  status ENUM('SENT','DEAD') NOT NULL,
  attempts INT NOT NULL,
  last_error VARCHAR(255) NULL,
  message TEXT NOT NULL,
  KEY idx_alert (alert_key(100), status, created_at)
);

CREATE TABLE IF NOT EXISTS selector_candidates (
  cand_id BIGINT AUTO_INCREMENT PRIMARY KEY,
  created_at DATETIME NOT NULL,
  platform VARCHAR(30) NOT NULL,
  selectors JSON NOT NULL,
  status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',
  decided_by VARCHAR(100) NULL,
  decided_at DATETIME NULL
);

CREATE TABLE IF NOT EXISTS audit_log (
  audit_id BIGINT AUTO_INCREMENT PRIMARY KEY,
  ts DATETIME NOT NULL,
  actor VARCHAR(100) NOT NULL,
  action VARCHAR(60) NOT NULL,
  before_state JSON NULL,
  after_state JSON NULL,
  KEY idx_ts (ts)
);

CREATE TABLE IF NOT EXISTS mi_observations (
  obs_id BIGINT AUTO_INCREMENT PRIMARY KEY,
  signal_type ENUM('SEARCH','BUYER','SKU','PRODUCT','PROMOTION','MEDIA') NOT NULL,
  period_start DATE NOT NULL,
  category_l VARCHAR(100) NOT NULL DEFAULT '',
  keyword VARCHAR(100) NOT NULL DEFAULT '',
  metric VARCHAR(40) NOT NULL,
  value DECIMAL(20,4) NOT NULL,
  source VARCHAR(60) NOT NULL DEFAULT '',
  UNIQUE KEY uq_mi (signal_type, period_start, category_l, keyword, metric),
  KEY idx_mi_period (signal_type, period_start)
);

CREATE TABLE IF NOT EXISTS mi_synonyms (
  alias VARCHAR(100) NOT NULL PRIMARY KEY,
  canonical VARCHAR(100) NOT NULL,
  updated_by VARCHAR(100) NOT NULL DEFAULT '',
  updated_at DATETIME NULL
);

CREATE TABLE IF NOT EXISTS crawler_settings (
  crawler_id VARCHAR(40) PRIMARY KEY,
  enabled TINYINT(1) NOT NULL DEFAULT 1,
  times JSON NULL,
  config JSON NULL,
  last_slot DATETIME NULL,
  updated_by VARCHAR(100) NULL,
  updated_at DATETIME NULL
);

CREATE TABLE IF NOT EXISTS crawler_runs (
  run_id BIGINT AUTO_INCREMENT PRIMARY KEY,
  crawler_id VARCHAR(40) NOT NULL,
  trigger_kind ENUM('SCHEDULED','MANUAL') NOT NULL,
  requested_by VARCHAR(100) NOT NULL DEFAULT '',
  status ENUM('QUEUED','RUNNING','OK','FAILED','SKIPPED') NOT NULL,
  queued_at DATETIME NOT NULL,
  started_at DATETIME NULL,
  finished_at DATETIME NULL,
  rows_loaded INT NOT NULL DEFAULT 0,
  message VARCHAR(500) NOT NULL DEFAULT '',
  KEY idx_crawler_runs (crawler_id, run_id)
);
